import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const AdminPanel = () => {
  const navigate = useNavigate();
  const storedUser = JSON.parse(localStorage.getItem('vrx_user') || '{}');

  // Tab State: analytics, users, fleet, finance
  const [activeTab, setActiveTab] = useState('analytics');

  // Data States
  const [stats, setStats] = useState({ totalRevenue: 0, activeRentals: 0, totalUsers: 0, fleetSize: 0 });
  const [bookings, setBookings] = useState([]);
  const [users, setUsers] = useState([]);
  const [fleet, setFleet] = useState([]);
  const [transactions, setTransactions] = useState([]);

  // Loading & Action States
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // New Vehicle Form State
  const [newVehicle, setNewVehicle] = useState({
    type: 'scooter',
    model: '',
    qrCode: '',
    pricePerHour: '',
    batteryLevel: 100,
    address: 'Academic Block A',
    lat: 22.8025,
    lng: 81.7515,
    featuresString: 'GPS Tracked, Insured'
  });

  // Verify authorization
  useEffect(() => {
    if (!storedUser._id || storedUser.role !== 'admin') {
      alert('Access Denied: Administrative privileges required.');
      navigate('/dashboard');
    } else {
      loadAllAdminData();
    }
  }, []);

  const loadAllAdminData = async () => {
    setLoading(true);
    setError('');
    try {
      const statsRes = await axios.get('http://localhost:5000/api/admin/stats');
      setStats(statsRes.data);

      const bookingsRes = await axios.get('http://localhost:5000/api/admin/bookings');
      setBookings(bookingsRes.data);

      const usersRes = await axios.get('http://localhost:5000/api/admin/users');
      setUsers(usersRes.data);

      const fleetRes = await axios.get('http://localhost:5000/api/vehicles');
      setFleet(fleetRes.data);

      const financeRes = await axios.get('http://localhost:5000/api/admin/finance');
      setTransactions(financeRes.data);
    } catch (err) {
      console.error(err);
      setError('Failed to fetch administrative records.');
    }
    setLoading(false);
  };

  // User Actions
  const handleUpdateRole = async (userId, role) => {
    try {
      await axios.put(`http://localhost:5000/api/admin/users/${userId}/role`, { role });
      alert('User role updated successfully.');
      loadAllAdminData();
    } catch (err) {
      alert('Failed to update user role.');
    }
  };

  const handleDeleteUser = async (userId) => {
    if (!window.confirm('Are you sure you want to delete this user? This will also remove bookings and transaction history.')) return;
    try {
      await axios.delete(`http://localhost:5000/api/admin/users/${userId}`);
      alert('User deleted.');
      loadAllAdminData();
    } catch (err) {
      alert('Failed to delete user.');
    }
  };

  // Fleet Actions
  const handleAddVehicle = async (e) => {
    e.preventDefault();
    const payload = {
      type: newVehicle.type,
      model: newVehicle.model,
      qrCode: newVehicle.qrCode,
      pricePerHour: parseFloat(newVehicle.pricePerHour),
      batteryLevel: parseInt(newVehicle.batteryLevel),
      features: newVehicle.featuresString.split(',').map(f => f.trim()).filter(Boolean),
      currentLocation: {
        address: newVehicle.address,
        lat: parseFloat(newVehicle.lat),
        lng: parseFloat(newVehicle.lng)
      }
    };

    try {
      await axios.post('http://localhost:5000/api/admin/vehicles', payload);
      alert('New vehicle added to IGNTU fleet.');
      setNewVehicle({
        type: 'scooter',
        model: '',
        qrCode: '',
        pricePerHour: '',
        batteryLevel: 100,
        address: 'Academic Block A',
        lat: 22.8025,
        lng: 81.7515,
        featuresString: 'GPS Tracked, Insured'
      });
      loadAllAdminData();
    } catch (err) {
      alert(err.response?.data?.error || 'Failed to add vehicle.');
    }
  };

  const handleDeleteVehicle = async (vehicleId) => {
    if (!window.confirm('Are you sure you want to remove this vehicle from the fleet?')) return;
    try {
      await axios.delete(`http://localhost:5000/api/admin/vehicles/${vehicleId}`);
      alert('Vehicle deleted successfully.');
      loadAllAdminData();
    } catch (err) {
      alert('Failed to delete vehicle.');
    }
  };

  const handleUpdateVehicleStatus = async (vehicleId, status) => {
    try {
      await axios.put(`http://localhost:5000/api/admin/vehicles/${vehicleId}`, { status });
      alert('Vehicle status updated.');
      loadAllAdminData();
    } catch (err) {
      alert('Failed to update status.');
    }
  };

  return (
    <div style={{ display: 'flex', minHeight: '100vh' }}>
      {/* Sidebar */}
      <div className="sidebar" style={{ backgroundColor: '#0F172A' }}>
        <div className="logo d-flex align-items-center gap-2">
          <img src="/assets/igntu_logo.png" alt="IGNTU Logo" style={{ height: '35px' }} />
          <div className="d-flex flex-column text-start">
            <span style={{ fontSize: '1rem', lineHeight: '1.2', color: 'white', fontWeight: '800' }}>IGNTU</span>
            <span style={{ fontSize: '0.65rem', color: '#94A3B8', fontWeight: '500' }}>VehicleRentx</span>
          </div>
        </div>
        <ul>
          <li>
            <button className={`w-100 text-start border-0 bg-transparent px-4 py-3 d-flex align-items-center gap-3 ${activeTab === 'analytics' ? 'text-white fw-bold bg-secondary bg-opacity-25 border-start border-3 border-primary' : 'text-white-50'}`} onClick={() => setActiveTab('analytics')}>
              <i className="fa-solid fa-chart-line" style={{ width: '20px' }}></i> Analytics
            </button>
          </li>
          <li>
            <button className={`w-100 text-start border-0 bg-transparent px-4 py-3 d-flex align-items-center gap-3 ${activeTab === 'users' ? 'text-white fw-bold bg-secondary bg-opacity-25 border-start border-3 border-primary' : 'text-white-50'}`} onClick={() => setActiveTab('users')}>
              <i className="fa-solid fa-users" style={{ width: '20px' }}></i> Users
            </button>
          </li>
          <li>
            <button className={`w-100 text-start border-0 bg-transparent px-4 py-3 d-flex align-items-center gap-3 ${activeTab === 'fleet' ? 'text-white fw-bold bg-secondary bg-opacity-25 border-start border-3 border-primary' : 'text-white-50'}`} onClick={() => setActiveTab('fleet')}>
              <i className="fa-solid fa-motorcycle" style={{ width: '20px' }}></i> Fleet Control
            </button>
          </li>
          <li>
            <button className={`w-100 text-start border-0 bg-transparent px-4 py-3 d-flex align-items-center gap-3 ${activeTab === 'finance' ? 'text-white fw-bold bg-secondary bg-opacity-25 border-start border-3 border-primary' : 'text-white-50'}`} onClick={() => setActiveTab('finance')}>
              <i className="fa-solid fa-file-invoice-dollar" style={{ width: '20px' }}></i> Financials
            </button>
          </li>
          <li style={{ marginTop: 'auto', borderTop: '1px solid rgba(255,255,255,0.08)' }}>
            <button className="w-100 text-start border-0 bg-transparent px-4 py-3 d-flex align-items-center gap-3 text-danger" onClick={() => navigate('/dashboard')}>
              <i className="fa-solid fa-arrow-left" style={{ width: '20px' }}></i> Exit Admin
            </button>
          </li>
        </ul>
      </div>

      {/* Main Content */}
      <div className="main-content" style={{ flex: 1, backgroundColor: '#F8FAFC', minHeight: '100vh', padding: '30px' }}>

        {/* Header banner */}
        <div className="d-flex justify-content-between align-items-center mb-4 bg-white p-3 rounded-4 shadow-sm">
          <div>
            <h3 className="fw-bold m-0 text-dark">IGNTU System Admin</h3>
            <small className="text-muted">Manage users, track fleet, and audit system finances</small>
          </div>
          <div className="d-flex align-items-center gap-3">
            <span className="badge bg-danger bg-opacity-10 text-danger px-3 py-2 rounded-pill fw-bold">Super Admin Mode</span>
            <button className="btn btn-sm btn-outline-dark rounded-circle p-2" onClick={loadAllAdminData} title="Reload Data">
              <i className="fa-solid fa-rotate"></i>
            </button>
          </div>
        </div>

        {error && <div className="alert alert-danger p-3 mb-4 rounded-3 fw-bold">{error}</div>}

        {loading ? (
          <div className="text-center py-5">
            <div className="spinner-border text-success" role="status"></div>
            <p className="mt-3 text-muted">Loading secure administrative data...</p>
          </div>
        ) : (
          <>
            {/* Tab 1: Analytics Overview */}
            {activeTab === 'analytics' && (
              <div>
                {/* Stats Cards */}
                <div className="row g-4 mb-4">
                  {[
                    { title: 'Total Revenue', value: `₹${stats.totalRevenue.toLocaleString()}`, icon: 'fa-wallet', color: 'text-success', bg: 'rgba(22, 163, 74, 0.1)' },
                    { title: 'Active Rentals', value: stats.activeRentals, icon: 'fa-route', color: 'text-warning', bg: 'rgba(217, 119, 6, 0.1)' },
                    { title: 'Registered Users', value: stats.totalUsers, icon: 'fa-users', color: 'text-primary', bg: 'rgba(29, 78, 216, 0.1)' },
                    { title: 'Total Fleet Size', value: stats.fleetSize, icon: 'fa-motorcycle', color: 'text-info', bg: 'rgba(6, 182, 212, 0.1)' }
                  ].map((stat, i) => (
                    <div className="col-md-3" key={i}>
                      <div className="bg-white p-4 rounded-4 shadow-sm d-flex align-items-center gap-3 border border-light">
                        <div style={{ width: '60px', height: '60px', borderRadius: '15px', background: stat.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '24px' }} className={stat.color}>
                          <i className={`fa-solid ${stat.icon}`}></i>
                        </div>
                        <div>
                          <h6 className="text-muted mb-1 small">{stat.title}</h6>
                          <h3 className="fw-bold m-0 text-dark">{stat.value}</h3>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>

                {/* Recent Bookings */}
                <div className="bg-white p-4 rounded-4 shadow-sm border border-light">
                  <h5 className="fw-bold mb-4 text-dark"><i className="fa-solid fa-list-check me-2 text-primary"></i>Recent Bookings</h5>
                  <div className="table-responsive">
                    <table className="table table-hover align-middle">
                      <thead className="table-light">
                        <tr>
                          <th>User</th>
                          <th>Vehicle</th>
                          <th>Start Time</th>
                          <th>Duration</th>
                          <th>Revenue</th>
                          <th>Status</th>
                        </tr>
                      </thead>
                      <tbody>
                        {bookings.map((b, i) => (
                          <tr key={b._id || i}>
                            <td>
                              <div className="fw-bold">{b.userId?.fullName || 'Deleted User'}</div>
                              <small className="text-muted">{b.userId?.email || 'N/A'}</small>
                            </td>
                            <td>{b.vehicleId?.model || 'Deleted Vehicle'} <span className="badge bg-light text-dark small">{b.vehicleId?.type}</span></td>
                            <td>{new Date(b.startTime || b.createdAt).toLocaleString('en-IN', { dateStyle: 'short', timeStyle: 'short' })}</td>
                            <td>{b.status === 'completed' ? `${b.durationMinutes} min` : '-'}</td>
                            <td className="fw-bold text-success">₹{b.totalCost}</td>
                            <td>
                              <span className={`badge px-3 py-2 rounded-pill ${b.status === 'active' ? 'bg-success bg-opacity-10 text-success' : b.status === 'completed' ? 'bg-primary bg-opacity-10 text-primary' : 'bg-danger bg-opacity-10 text-danger'}`}>
                                {b.status}
                              </span>
                            </td>
                          </tr>
                        ))}
                        {bookings.length === 0 && (
                          <tr>
                            <td colSpan="6" className="text-center text-muted py-4">No bookings found.</td>
                          </tr>
                        )}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            )}

            {/* Tab 2: Users Management */}
            {activeTab === 'users' && (
              <div className="bg-white p-4 rounded-4 shadow-sm border border-light">
                <h5 className="fw-bold mb-4 text-dark"><i className="fa-solid fa-users-gear me-2 text-primary"></i>Users List</h5>
                <div className="table-responsive">
                  <table className="table table-hover align-middle">
                    <thead className="table-light">
                      <tr>
                        <th>Name</th>
                        <th>Email</th>
                        <th>Phone</th>
                        <th>ID Card / Student ID</th>
                        <th>Wallet Balance</th>
                        <th>Role</th>
                        <th>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {users.map((u) => (
                        <tr key={u._id}>
                          <td className="fw-bold">{u.fullName}</td>
                          <td>{u.email}</td>
                          <td>{u.phone || 'N/A'}</td>
                          <td><code>{u.studentId || 'N/A'}</code></td>
                          <td className="fw-bold text-primary">₹{u.walletBalance}</td>
                          <td>
                            <select className="form-select form-select-sm" value={u.role || 'student'} onChange={(e) => handleUpdateRole(u._id, e.target.value)}>
                              <option value="student">Student</option>
                              <option value="faculty">Faculty</option>
                              <option value="visitor">Visitor</option>
                              <option value="admin">Admin</option>
                            </select>
                          </td>
                          <td>
                            <button className="btn btn-sm btn-outline-danger" onClick={() => handleDeleteUser(u._id)} disabled={u.email === storedUser.email}>
                              <i className="fa-solid fa-trash"></i>
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Tab 3: Fleet Control */}
            {activeTab === 'fleet' && (
              <div className="row g-4">
                {/* Add Vehicle Form */}
                <div className="col-lg-4">
                  <div className="bg-white p-4 rounded-4 shadow-sm border border-light">
                    <h5 className="fw-bold mb-3 text-dark"><i className="fa-solid fa-plus text-success me-2"></i>Add Vehicle</h5>
                    <form onSubmit={handleAddVehicle}>
                      <div className="mb-2">
                        <label className="form-label small text-muted fw-bold">VEHICLE TYPE</label>
                        <select className="form-select bg-light border-0 p-2 rounded-3" value={newVehicle.type} onChange={e => setNewVehicle({...newVehicle, type: e.target.value})}>
                          <option value="bicycle">Bicycle</option>
                          <option value="ebike">E-Bike</option>
                          <option value="scooter">Electric Scooter</option>
                          <option value="bike">Motorcycle</option>
                          <option value="bike-taxi">Bike Taxi</option>
                          <option value="car-rental">Car Rental</option>
                        </select>
                      </div>
                      <div className="mb-2">
                        <label className="form-label small text-muted fw-bold">MODEL NAME</label>
                        <input type="text" required className="form-control bg-light border-0 p-2 rounded-3" placeholder="Ather 450X" value={newVehicle.model} onChange={e => setNewVehicle({...newVehicle, model: e.target.value})} />
                      </div>
                      <div className="mb-2">
                        <label className="form-label small text-muted fw-bold">QR CODE ID</label>
                        <input type="text" required className="form-control bg-light border-0 p-2 rounded-3" placeholder="QR123" value={newVehicle.qrCode} onChange={e => setNewVehicle({...newVehicle, qrCode: e.target.value})} />
                      </div>
                      <div className="mb-2">
                        <label className="form-label small text-muted fw-bold">PRICE PER HOUR (₹)</label>
                        <input type="number" required className="form-control bg-light border-0 p-2 rounded-3" placeholder="30" value={newVehicle.pricePerHour} onChange={e => setNewVehicle({...newVehicle, pricePerHour: e.target.value})} />
                      </div>
                      <div className="mb-2">
                        <label className="form-label small text-muted fw-bold">BATTERY LEVEL (%)</label>
                        <input type="number" max="100" className="form-control bg-light border-0 p-2 rounded-3" placeholder="100" value={newVehicle.batteryLevel} onChange={e => setNewVehicle({...newVehicle, batteryLevel: e.target.value})} />
                      </div>
                      <div className="mb-2">
                        <label className="form-label small text-muted fw-bold">STAND ADDRESS</label>
                        <input type="text" required className="form-control bg-light border-0 p-2 rounded-3" placeholder="Academic Block A" value={newVehicle.address} onChange={e => setNewVehicle({...newVehicle, address: e.target.value})} />
                      </div>
                      <div className="row">
                        <div className="col-6 mb-2">
                          <label className="form-label small text-muted fw-bold">LATITUDE</label>
                          <input type="number" step="any" required className="form-control bg-light border-0 p-2 rounded-3" placeholder="22.8025" value={newVehicle.lat} onChange={e => setNewVehicle({...newVehicle, lat: e.target.value})} />
                        </div>
                        <div className="col-6 mb-2">
                          <label className="form-label small text-muted fw-bold">LONGITUDE</label>
                          <input type="number" step="any" required className="form-control bg-light border-0 p-2 rounded-3" placeholder="81.7515" value={newVehicle.lng} onChange={e => setNewVehicle({...newVehicle, lng: e.target.value})} />
                        </div>
                      </div>
                      <div className="mb-3">
                        <label className="form-label small text-muted fw-bold">FEATURES (comma-separated)</label>
                        <input type="text" className="form-control bg-light border-0 p-2 rounded-3" value={newVehicle.featuresString} onChange={e => setNewVehicle({...newVehicle, featuresString: e.target.value})} />
                      </div>
                      <button type="submit" className="btn btn-primary-custom w-100 py-2 rounded-pill">
                        <i className="fa-solid fa-plus-circle me-1"></i> Add to Fleet
                      </button>
                    </form>
                  </div>
                </div>

                {/* Fleet List */}
                <div className="col-lg-8">
                  <div className="bg-white p-4 rounded-4 shadow-sm border border-light h-100">
                    <h5 className="fw-bold mb-4 text-dark"><i className="fa-solid fa-motorcycle me-2 text-primary"></i>Active Fleet ({fleet.length})</h5>
                    <div className="table-responsive" style={{ maxHeight: '550px', overflowY: 'auto' }}>
                      <table className="table table-hover align-middle">
                        <thead className="table-light">
                          <tr>
                            <th>Model</th>
                            <th>Type</th>
                            <th>QR Code</th>
                            <th>Price/Hr</th>
                            <th>Battery</th>
                            <th>Status</th>
                            <th>Actions</th>
                          </tr>
                        </thead>
                        <tbody>
                          {fleet.map((v) => (
                            <tr key={v._id}>
                              <td>
                                <div className="fw-bold">{v.model}</div>
                                <small className="text-muted"><i className="fa-solid fa-location-dot me-1 text-danger"></i>{v.currentLocation?.address || 'N/A'}</small>
                              </td>
                              <td className="text-uppercase small fw-bold text-muted">{v.type}</td>
                              <td><code>{v.qrCode}</code></td>
                              <td className="fw-bold text-success">₹{v.pricePerHour}</td>
                              <td>{v.batteryLevel ? `${v.batteryLevel}%` : 'N/A'}</td>
                              <td>
                                <select className={`form-select form-select-sm fw-bold ${v.status === 'available' ? 'text-success' : 'text-danger'}`} value={v.status} onChange={(e) => handleUpdateVehicleStatus(v._id, e.target.value)}>
                                  <option value="available" className="text-success">Available</option>
                                  <option value="booked" className="text-primary">Booked</option>
                                  <option value="maintenance" className="text-warning">Maintenance</option>
                                  <option value="inactive" className="text-muted">Inactive</option>
                                </select>
                              </td>
                              <td>
                                <button className="btn btn-sm btn-outline-danger" onClick={() => handleDeleteVehicle(v._id)}>
                                  <i className="fa-solid fa-trash"></i>
                                </button>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Tab 4: Financial Transactions */}
            {activeTab === 'finance' && (
              <div className="bg-white p-4 rounded-4 shadow-sm border border-light">
                <h5 className="fw-bold mb-4 text-dark"><i className="fa-solid fa-receipt me-2 text-primary"></i>Financial Transactions Log</h5>
                <div className="table-responsive">
                  <table className="table table-hover align-middle">
                    <thead className="table-light">
                      <tr>
                        <th>User</th>
                        <th>Email</th>
                        <th>Transaction Info</th>
                        <th>Method</th>
                        <th>Amount</th>
                        <th>Date & Time</th>
                      </tr>
                    </thead>
                    <tbody>
                      {transactions.map((tx, i) => (
                        <tr key={tx._id || i}>
                          <td className="fw-bold">{tx.userId?.fullName || 'System Seed'}</td>
                          <td>{tx.userId?.email || 'N/A'}</td>
                          <td>
                            <div className="fw-bold">{tx.description}</div>
                            <small className="text-muted text-uppercase">{tx.type}</small>
                          </td>
                          <td><span className="badge bg-light text-dark">{tx.paymentMethod}</span></td>
                          <td className={`fw-bold ${tx.type === 'topup' || tx.type === 'refund' ? 'text-success' : 'text-danger'}`}>
                            {tx.type === 'topup' || tx.type === 'refund' ? '+' : '-'}₹{tx.amount}
                          </td>
                          <td>{new Date(tx.createdAt).toLocaleString('en-IN')}</td>
                        </tr>
                      ))}
                      {transactions.length === 0 && (
                        <tr>
                          <td colSpan="6" className="text-center text-muted py-4">No transactions recorded.</td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

export default AdminPanel;
